(6172433, 910184, 53147, '<td valign="top">Glad to see this ribbon. Excellent image. Congrats!</td>', 'Glad to see this ribbon. Excellent image. Congrats!', '2010-09-27 01:56:17.000000', NULL, 0),
(6172437, 909371, 53147, '<td valign="top">Glad to see this ribbon as well. Pleasure sharing front page space with yours and 3rd place as well.</td>', 'Glad to see this ribbon as well. Pleasure sharing front page space with yours and 3rd place as well.', '2010-09-27 01:56:58.000000', NULL, 0),
(6172439, 909371, 104809, '<td valign="top">I really like the composition here, but am I the only one bothered by the heavy aliasing artifacts?  I''m afraid I didn''t really give this a great score due to my perception on the image quality, but I sincerely like everything else about this.</td>', 'I really like the composition here, but am I the only one bothered by the heavy aliasing artifacts?  I''m afraid I didn''t really give this a great score due to my perception on the image quality, but I sincerely like everything else about this.', '2010-09-27 01:58:35.000000', NULL, 0),
(6172440, 910285, 5112, '<td valign="top">Nice macro work!  Yeah.  Shallow DOF, a good subject, a bit of a diagonal, I like it!</td>', 'Nice macro work!  Yeah.  Shallow DOF, a good subject, a bit of a diagonal, I like it!', '2010-09-27 01:59:57.000000', NULL, 0),
(6172441, 910013, 104809, '<td valign="top">I feel like I''m in good company by liking this one.  I was one of the 9''s.</td>', 'I feel like I''m in good company by liking this one.  I was one of the 9''s.', '2010-09-27 02:01:08.000000', NULL, 0),
